NEW_FILES = {'ticket_queue.py': '"""ticket_queue.py -- a box office sells through a ticket window, and its queue stands in front of it (pure, no bpy).\n\nThe factory\'s roadmap 267. The walker, 2026-10-20, asked what arena_a02\'s four steel barricades on its event floor were\nfor, and answered "queue lanes to the box office"; then "stanchion or stanchions are likley more common for banks and\nindoor common areas", "metal barriers are for outdoor concerts or riot protection from police", "retractable belt\nstanchion", and a photo -- black posts on round bases, flat black belts taut at waist height, lanes switching back in\nfront of a desk. Zoo 1.119.0 draws one straight run of those stanchions, `stanchion_run`; this lays a queue of them.\n\nTHE RULE (`queue_box_offices`, run by `level_design.enrich` before cover and furniture, and by\n`migrate_ticket_queue.py` over the library). A room whose id names a box office or a ticket office (`is_box_office`)\nand that shares an interior wall with a public room (`is_public`: the role `public_entry`, or a lobby or a hall by its\nwords) gets:\n\n  * A TICKET WINDOW in that wall -- a `window` opening tagged `ticket_window`, `WINDOW_W` wide over a counter\'s sill,\n    sealed (no `breakable`: a pane that shot out would be a firing line into the room behind it), on the builder\'s\n    grid so it is cut where the queue was laid for it.\n  * A QUEUE in front of it, on the public side: `lanes` lanes, two or three, between lines of stanchion runs parallel to\n    the wall, each line one `stanchion_run_<q>_<k>` volume. The lines stop a turn short at alternate ends, so the queue\n    switches back: in at the end away from the window, out of the last lane at the window\'s end into the floor in front\n    of the window. Nothing closes a lane\'s open end; a run is one straight slot (Zoo\'s species), and a corner post two\n    runs shared would stand two posts in one place.\n\nEVERY CLEARANCE IS THE CONTRACT\'S (`agent_contract`):\n  * a lane is a corridor to the nav bake, so its clear floor between two lines\' slots is `stair_flight_width()` -- the\n    corridor minimum and one bake cell, "a corridor AT the minimum keeps a strip whose joining depends on where the\n    voxel grid falls" -- and a turn is as wide;\n  * the floor in front of the window, wall to the first line, is `door_approach()`: what a body needs to use a door;\n  * the queue keeps `min_corridor_width()` from every wall but its own, every standing volume, every stair\'s reserve,\n    every hole in its floor and every vault\'s swing, so a body walks round it; and from every walkable opening\'s\n    approach -- its span along its wall, `door_approach()` deep both sides -- so it never stands in a doorway\'s way.\n\nTHE NUMBERS ARE ZOO\'S where they are a stanchion\'s: `RUN_DEPTH` and `RUN_HEIGHT`, `stanchion_run`\'s genome defaults --\na 14 in base, a 38 in post. Retyped because Deli Counter builds without Zoo beside it; `test_ticket_queue.py` pins them\nto the genome when the zoo repo is found next to this one, as `test_vault_room.py` pins the vault door\'s.\n\nWHAT IT DOES NOT DO, said so it is not read as an oversight: a box office on an EXTERIOR wall -- a theatre\'s window on\nthe street -- is the street\'s queue, and the street is Lot\'s; this reports it and lays nothing. A bank\'s teller line\ntakes a queue the same way and does not get one yet (the factory\'s roadmap). A queue that cannot fit two lanes clear\nof all of the above is not laid, and the report says why.\n"""\nfrom __future__ import annotations\n\nimport math\n\nimport agent_contract\n\n# ------------------------------------------------------------ Zoo\'s numbers\n#: `stanchion_run`\'s genome defaults (Zoo 1.119.0): the run\'s slot is a base\'s diameter deep and a post\'s height tall.\nRUN_DEPTH = 0.356\nRUN_HEIGHT = 0.97\n#: the species\' own kind (the dartboard\'s rule, `level_design._PROP_MATERIALS`): its stem carries no `_m`\nRUN_MATERIAL = "metal_painted"\nRUN_ACOUSTIC = ("Metal", 0.25, 0.2)\n#: `stanchion_run`\'s genome range: a line shorter than this is not a run Zoo draws\nRUN_MIN = 1.1\n\n# ------------------------------------------------------------ the window\n#: a box office\'s window, about 4 ft wide, at a counter\'s sill, its head at a door\'s\nWINDOW_W = 1.2\nWINDOW_SILL = 1.0\nWINDOW_H = 1.1\n#: what a window\'s jamb keeps from a wall\'s end or another opening (`layout_lint.LEAF_MARGIN`)\nJAMB = 0.3\n\n# ------------------------------------------------------------ the queue\nLANES = (3, 2)\n#: a queue\'s length along its wall: long enough that a line is a run of two belts, short of a stadium\'s\nMAX_SPAN = 6.0\n#: the steps a span is shortened by while it is fitted\nSPAN_STEP = 0.1\n\n#: words that name a room that sells tickets, as whole tokens of its id (`box` alone is a box room; with `office` it\n#: is a box office)\n_TICKET_TOKENS = frozenset(("ticket", "tickets", "ticketing", "boxoffice"))\n_BOX_OFFICE = frozenset(("box", "office"))\n_PUBLIC_ROLES = frozenset(("public_entry",))\n_PUBLIC_KINDS = frozenset(("lobby", "hall"))\n#: the openings a body walks through, whose approaches a queue keeps clear of\n_WALKABLE = ("door", "garage", "breach", "vault")\n\n\ndef lane_clear():\n    """The clear floor across a lane, between two lines\' slots, and across a turn: a stair flight\'s width."""\n    return agent_contract.stair_flight_width()\n\n\ndef pitch():\n    """Line to line, centre to centre."""\n    return lane_clear() + RUN_DEPTH\n\n\ndef service_depth():\n    """The floor in front of the window, from the wall\'s face to the first line\'s slot."""\n    return agent_contract.door_approach()\n\n\ndef line_min():\n    """The shortest line beside its turn: as long as the lanes are wide, or a lane reads as a pen."""\n    return pitch()\n\n\ndef is_box_office(room):\n    tokens = set(str(room.get("id", "")).lower().replace("-", "_").split("_"))\n    return bool(tokens & _TICKET_TOKENS) or _BOX_OFFICE <= tokens\n\n\ndef is_public(room, building=None):\n    if str(room.get("role") or "").lower() in _PUBLIC_ROLES:\n        return True\n    import level_design\n    return level_design._room_kind(room, building) in _PUBLIC_KINDS\n\n\ndef _box_gap(a, b):\n    import level_design\n    return level_design._box_gap(a, b)\n\n\ndef _opening_width(op):\n    """An opening\'s width as the builder resolves it (`spec_types.Opening.resolved`)."""\n    if op.get("width") is not None:\n        return float(op["width"])\n    if op.get("kind", "door") == "vault":\n        import vault_room\n        return float(vault_room.resolved_aperture(op)["width"])\n    defaults = {"door": agent_contract.min_door_width(), "window": 1.6, "garage": 3.5, "breach": 1.5,\n                "teller": 2.0, "safe_deposit": 2.0}\n    return float(defaults.get(op.get("kind", "door"), 1.6))\n\n\ndef _walls(spec):\n    """Every partition as ``(index, p, axis, line, lo, hi)``, its run as the builder stands it."""\n    hx = float(spec.get("footprint_x") or 0.0) / 2.0\n    hy = float(spec.get("footprint_y") or 0.0) / 2.0\n    out = []\n    for i, p in enumerate(spec.get("partitions") or []):\n        ax = str(p.get("axis", "X")).upper()\n        b = hx if ax == "X" else hy\n        s = -b if p.get("start") is None else float(p["start"])\n        e = b if p.get("end") is None else float(p["end"])\n        out.append((i, p, ax, float(p.get("pos", 0.0)), min(s, e), max(s, e)))\n    return out\n\n\ndef _shared_walls(spec, office):\n    """The partitions between `office` and a public room on its storey: ``(wall, public room, side)``, `side` the\n    direction (+1 / -1 on the wall\'s perpendicular axis) from the wall into the public room."""\n    story = int(office.get("story", 0) or 0)\n    building = __import__("level_design").club_building_id(spec)\n    ox0, oy0, ox1, oy1 = office["bounds"]\n    out = []\n    for w in _walls(spec):\n        _i, p, ax, line, lo, hi = w\n        if int(p.get("story", 0) or 0) != story:\n            continue\n        # the office\'s edge on this wall\'s line, and which side of it the office is\n        if ax == "X":\n            o_lo, o_hi = ox0, ox1\n            o_side = -1 if abs(oy1 - line) < 1e-6 else (1 if abs(oy0 - line) < 1e-6 else 0)\n        else:\n            o_lo, o_hi = oy0, oy1\n            o_side = -1 if abs(ox1 - line) < 1e-6 else (1 if abs(ox0 - line) < 1e-6 else 0)\n        if o_side == 0 or min(o_hi, hi) - max(o_lo, lo) < WINDOW_W + 2 * JAMB:\n            continue\n        for r in spec.get("rooms") or []:\n            if r is office or int(r.get("story", 0) or 0) != story or not r.get("bounds"):\n                continue\n            rx0, ry0, rx1, ry1 = r["bounds"]\n            if ax == "X":\n                r_lo, r_hi = rx0, rx1\n                r_side = 1 if abs(ry0 - line) < 1e-6 else (-1 if abs(ry1 - line) < 1e-6 else 0)\n            else:\n                r_lo, r_hi = ry0, ry1\n                r_side = 1 if abs(rx0 - line) < 1e-6 else (-1 if abs(rx1 - line) < 1e-6 else 0)\n            if r_side == 0 or r_side == o_side:\n                continue\n            if min(o_hi, r_hi, hi) - max(o_lo, r_lo, lo) < WINDOW_W + 2 * JAMB:\n                continue\n            if not is_public(r, building):\n                continue\n            out.append((w, r, r_side))\n    return out\n\n\ndef _world(ax, line, face, side, u, v):\n    """Wall-local (u along the wall, v from its face into the public room) to world plan (x, y)."""\n    b = line + side * face + side * v\n    return (u, b) if ax == "X" else (b, u)\n\n\ndef _rect(ax, line, face, side, u0, u1, v0, v1):\n    x0, y0 = _world(ax, line, face, side, u0, v0)\n    x1, y1 = _world(ax, line, face, side, u1, v1)\n    return (min(x0, x1), min(y0, y1), max(x0, x1), max(y0, y1))\n\n\ndef _keepouts(spec, story, wall_index, room_rect):\n    """What a queue on `story` keeps `min_corridor_width()` from, as plan boxes with a name: walls but the queue\'s\n    own, walkable openings\' approaches, standing volumes, stairs, holes, vaults\' swings; and the points it keeps the\n    same distance from: ladders, and markers on the floor. ONLY WHAT IS IN THE PUBLIC ROOM: each box clipped to\n    `room_rect` and dropped when nothing of it is left, each point dropped outside it -- the office\'s furniture and the\n    walls standing on the office\'s side of the shared wall are behind that wall, and a cabinet 0.6 m behind it would\n    otherwise have refused every queue in front of it."""\n    import level_design\n    import vault_room\n    sh = level_design._story_height(spec)\n    floor = story * sh\n    t = float(spec.get("wall_thick", 0.3) or 0.3)\n    hx = float(spec.get("footprint_x") or 0.0) / 2.0\n    hy = float(spec.get("footprint_y") or 0.0) / 2.0\n    boxes = [("wall N", (-hx, hy - t / 2, hx, hy + t / 2)), ("wall S", (-hx, -hy - t / 2, hx, -hy + t / 2)),\n             ("wall E", (hx - t / 2, -hy, hx + t / 2, hy)), ("wall W", (-hx - t / 2, -hy, -hx + t / 2, hy))]\n    for i, p, ax, line, lo, hi in _walls(spec):\n        if int(p.get("story", 0) or 0) != story or i == wall_index:\n            continue\n        boxes.append(("partition %d" % i, (lo, line - t / 2, hi, line + t / 2) if ax == "X"\n                      else (line - t / 2, lo, line + t / 2, hi)))\n    da = agent_contract.door_approach()\n    for e in vault_room.wall_openings(spec, kinds=_WALKABLE):\n        if e["story"] != story:\n            continue\n        w = _opening_width(e["op"]) / 2.0\n        d = t / 2 + da\n        boxes.append(("%s approach at (%.2f, %.2f)" % (e["op"].get("kind", "door"), e["x"], e["y"]),\n                      (e["along"] - w, e["line"] - d, e["along"] + w, e["line"] + d) if e["axis"] == "X"\n                      else (e["line"] - d, e["along"] - w, e["line"] + d, e["along"] + w)))\n    for v in spec.get("volumes") or []:\n        vz, vh = float(v.get("z", 0.0)), float(v.get("size_z", 0.0))\n        if not level_design._on_storey(vz, vh, floor, sh) or level_design._hung(v, floor):\n            continue\n        ax_, ay_ = float(v.get("size_x", 1)) / 2.0, float(v.get("size_y", 1)) / 2.0\n        boxes.append(("volume %s" % v.get("name"), (v["x"] - ax_, v["y"] - ay_, v["x"] + ax_, v["y"] + ay_)))\n    for r in level_design._stair_reserved_rects(spec):\n        boxes.append(("a stair", tuple(r)))\n    for h in spec.get("slab_holes") or []:\n        if int(h.get("story", 0) or 0) == story:\n            boxes.append(("a floor hole", (h["x"] - h["size_x"] / 2.0, h["y"] - h["size_y"] / 2.0,\n                                           h["x"] + h["size_x"] / 2.0, h["y"] + h["size_y"] / 2.0)))\n    for r in vault_room.keepout_rects(spec, story):\n        boxes.append(("a vault door\'s swing", tuple(r)))\n    head = agent_contract.min_headroom()\n    points = []\n    for lad in spec.get("ladders") or []:\n        if int(lad.get("from_story", 0) or 0) <= story <= int(lad.get("to_story", 0) or 0):\n            points.append(("a ladder", (lad["x"], lad["y"])))\n    for m in spec.get("markers") or []:\n        z = float(m.get("z", 0.0) or 0.0)\n        if floor - 0.05 <= z <= floor + head:\n            points.append(("marker %s" % m.get("type"), (m.get("x", 0.0), m.get("y", 0.0))))\n    rx0, ry0, rx1, ry1 = room_rect\n    kept = []\n    for name, (x0, y0, x1, y1) in boxes:\n        c = (max(x0, rx0), max(y0, ry0), min(x1, rx1), min(y1, ry1))\n        if c[2] - c[0] > 1e-6 and c[3] - c[1] > 1e-6:\n            kept.append((name, c))\n    points = [(n, (px, py)) for n, (px, py) in points if rx0 <= px <= rx1 and ry0 <= py <= ry1]\n    return kept, points\n\n\ndef _overlaps(a, b):\n    return a[0] < b[2] - 1e-9 and b[0] < a[2] - 1e-9 and a[1] < b[3] - 1e-9 and b[1] < a[3] - 1e-9\n\n\ndef _clash(rect, line_boxes, boxes, points, room_rect):\n    """What stops a queue, or None. TWO QUESTIONS, because the queue is mostly floor: the floor in front of the window\n    and the lanes are walked, and only the lines stand. Nothing may stand INSIDE the queue\'s rectangle, wall face to\n    last line -- a crate in a lane, a doorway\'s approach under the window -- and each LINE keeps a corridor from\n    everything, so a body passes every end and every side of the queue. The first draft held the whole rectangle a\n    corridor off everything, as if the lanes were solid, and on arena_a02 nothing fitted between the event floor\'s\n    west breach and the box office\'s door."""\n    cw = agent_contract.min_corridor_width()\n    rx0, ry0, rx1, ry1 = room_rect\n    if rect[0] < rx0 - 1e-9 or rect[1] < ry0 - 1e-9 or rect[2] > rx1 + 1e-9 or rect[3] > ry1 + 1e-9:\n        return "the public room\'s bounds"\n    for name, b in boxes:\n        if _overlaps(rect, b):\n            return name + " inside the queue"\n    for name, (px, py) in points:\n        if rect[0] <= px <= rect[2] and rect[1] <= py <= rect[3]:\n            return name + " inside the queue"\n    for lb in line_boxes:\n        for name, b in boxes:\n            if _box_gap(lb, b) < cw - 1e-9:\n                return "%s within %.2f m of a line" % (name, cw)\n        for name, (px, py) in points:\n            if _box_gap(lb, (px, py, px, py)) < cw - 1e-9:\n                return "%s within %.2f m of a line" % (name, cw)\n    return None\n\n\ndef _lines(ua, ub, window_high, lanes):\n    """Each line\'s span along the wall and its offset from the wall\'s face (to the slot\'s centre): ``[(u0, u1, v)]``.\n    Line 0 is nearest the wall, and stops a turn short at the window\'s end -- the way out to the window -- and the\n    lines after it stop short at alternate ends."""\n    turn = lane_clear()\n    v0 = service_depth() + RUN_DEPTH / 2.0\n    out = []\n    for k in range(lanes + 1):\n        short_at_window = (k % 2 == 0)\n        if short_at_window == window_high:\n            u0, u1 = ua, ub - turn\n        else:\n            u0, u1 = ua + turn, ub\n        out.append((u0, u1, v0 + k * pitch()))\n    return out\n\n\ndef plan(spec, office):\n    """The best ticket window and queue for `office`, or the reason there is none: ``{"ok", "why", ...}``.\n\n    Every window centre the builder\'s grid allows on each shared wall, the window at either end of the queue, three\n    lanes then two, the queue as long as `MAX_SPAN` then shorter by `SPAN_STEP`, down to a line of `line_min()` beside\n    its turn: the first that clears everything (`_keepouts`, `_clash`) inside the public room. Preferred: more lanes, then a\n    longer queue, then a window nearer the middle of the office\'s wall, then the lower window centre."""\n    import vault_room\n    story = int(office.get("story", 0) or 0)\n    walls = _shared_walls(spec, office)\n    if not walls:\n        return {"ok": False, "why": "no interior wall shared with a public room"}\n    t = float(spec.get("wall_thick", 0.3) or 0.3)\n    face = t / 2.0\n    g = vault_room._grid(spec)\n    turn = lane_clear()\n    cw = agent_contract.min_corridor_width()\n    best, best_key, last_why = None, None, "nothing fits"\n    for (wall, room, side) in walls:\n        wi, p, ax, line, lo, hi = wall\n        ox0, oy0, ox1, oy1 = office["bounds"]\n        rx0, ry0, rx1, ry1 = room["bounds"]\n        room_rect = (rx0, ry0, rx1, ry1)\n        o_lo, o_hi = (ox0, ox1) if ax == "X" else (oy0, oy1)\n        r_lo, r_hi = (rx0, rx1) if ax == "X" else (ry0, ry1)\n        # the window: in the run the office, the public room and the wall all share, a jamb off its ends\n        s_lo, s_hi = max(o_lo, r_lo, lo), min(o_hi, r_hi, hi)\n        seg_lo, seg_hi = s_lo + face + JAMB + WINDOW_W / 2.0, s_hi - face - JAMB - WINDOW_W / 2.0\n        mid = (s_lo + s_hi) / 2.0\n        boxes, points = _keepouts(spec, story, wi, room_rect)\n        # the openings already in this wall: the window keeps a jamb from each, and from a wall ending on it\n        spans = []\n        for e in vault_room.wall_openings(spec, kinds=("door", "window", "garage", "breach", "vault", "teller",\n                                                       "safe_deposit")):\n            if e["host"] is p:\n                hw = _opening_width(e["op"]) / 2.0\n                spans.append((e["along"] - hw, e["along"] + hw))\n        for j, q, qax, qline, qlo, qhi in _walls(spec):\n            if qax != ax and int(q.get("story", 0) or 0) == story and qlo - face <= line <= qhi + face:\n                spans.append((qline - face, qline + face))\n        centre = (lo + hi) / 2.0\n        k_lo = math.ceil((seg_lo - centre) / g - 1e-9)\n        k_hi = math.floor((seg_hi - centre) / g + 1e-9)\n        for kk in range(k_lo, k_hi + 1):\n            wc = centre + kk * g\n            w0, w1 = wc - WINDOW_W / 2.0, wc + WINDOW_W / 2.0\n            if any(a - JAMB < w1 and w0 < b + JAMB for a, b in spans):\n                last_why = "no place on the wall clears its openings and the walls ending on it"\n                continue\n            for window_high in (True, False):\n                for lanes in LANES:\n                    depth = service_depth() + RUN_DEPTH + lanes * pitch()\n                    span = MAX_SPAN\n                    while span >= turn + line_min() - 1e-9:\n                        ub = wc + turn / 2.0 if window_high else wc - turn / 2.0 + span\n                        ua = ub - span\n                        rect = _rect(ax, line, face, side, ua, ub, 0.0, depth)\n                        line_boxes = [_rect(ax, line, face, side, u0, u1, v - RUN_DEPTH / 2.0, v + RUN_DEPTH / 2.0)\n                                      for (u0, u1, v) in _lines(ua, ub, window_high, lanes)]\n                        why = _clash(rect, line_boxes, boxes, points, room_rect)\n                        if why is None:\n                            key = (lanes, round(span, 6), -abs(wc - mid), -wc)\n                            if best_key is None or key > best_key:\n                                best_key = key\n                                best = {"ok": True, "why": "", "wall": wall, "room": room, "side": side,\n                                        "window_u": wc, "window_high": window_high, "lanes": lanes,\n                                        "span": (ua, ub), "depth": depth, "rect": rect}\n                            break\n                        last_why = why\n                        span = round(span - SPAN_STEP, 6)\n    if best is None:\n        return {"ok": False, "why": last_why}\n    wi, p, ax, line, lo, hi = best["wall"]\n    ua, ub = best["span"]\n    best["lines"] = []\n    for (u0, u1, v) in _lines(ua, ub, best["window_high"], best["lanes"]):\n        cx, cy = _world(ax, line, face, best["side"], (u0 + u1) / 2.0, v)\n        length = u1 - u0\n        best["lines"].append({"x": cx, "y": cy, "length": length,\n                              "size": (length, RUN_DEPTH) if ax == "X" else (RUN_DEPTH, length)})\n    return best\n\n\ndef _declare_material(spec):\n    """Declare `RUN_MATERIAL` LAST, after the finish palette: a slot\'s style is its material\'s place in the palette\n    and `floors.ensure_finish_palette` appends the finish materials after the authored list, so a material appended\n    to the authored list ahead of them would move every finish slot\'s style by one (Deli Counter 0.242.0 moved 50\n    on arena_a02 that way, and declared the palette instead)."""\n    import floors\n    have = [m.get("id") for m in spec.get("materials") or []]\n    if RUN_MATERIAL in have:\n        return\n    mats = spec.setdefault("materials", [])\n    for m in floors.FINISH_PALETTE:\n        if m["id"] not in have:\n            mats.append(dict(m))\n    a, absorption, damping = RUN_ACOUSTIC\n    mats.append({"id": RUN_MATERIAL, "acoustic": a, "absorption": absorption, "damping": damping})\n\n\ndef queue_box_offices(spec):\n    """Give every box office a ticket window and its queue. Idempotent: a spec that already has a `ticket_window`\n    opening or a `stanchion_run_*` volume is left alone. Returns ``[report]``, one per box office:\n    ``{"room", "queued": bool, "why", "lanes", "runs"}``."""\n    report = []\n    if any(op.get("tag") == "ticket_window" for p in spec.get("partitions") or [] for op in p.get("openings") or []):\n        return report\n    if any(str(v.get("name", "")).startswith("stanchion_run_") for v in spec.get("volumes") or []):\n        return report\n    if not spec.get("footprint_x") or not spec.get("footprint_y"):\n        return report\n    import level_design\n    sh = level_design._story_height(spec)\n    q = 0\n    for office in spec.get("rooms") or []:\n        if not office.get("bounds") or not is_box_office(office):\n            continue\n        entry = {"room": office.get("id"), "queued": False, "why": "", "lanes": 0, "runs": []}\n        report.append(entry)\n        got = plan(spec, office)\n        if not got["ok"]:\n            entry["why"] = got["why"]\n            continue\n        wi, p, ax, line, lo, hi = got["wall"]\n        centre, run = (lo + hi) / 2.0, hi - lo\n        p.setdefault("openings", []).append({\n            "kind": "window", "pos": round((got["window_u"] - centre) / run, 6), "width": WINDOW_W,\n            "height": WINDOW_H, "sill": WINDOW_SILL, "vaultable": False, "tag": "ticket_window"})\n        floor = int(office.get("story", 0) or 0) * sh\n        for k, ln in enumerate(got["lines"]):\n            name = "stanchion_run_%d_%d" % (q, k)\n            spec.setdefault("volumes", []).append({\n                "name": name, "x": round(ln["x"], 3), "y": round(ln["y"], 3),\n                "z": round(floor + RUN_HEIGHT / 2.0, 3),\n                "size_x": round(ln["size"][0], 3), "size_y": round(ln["size"][1], 3), "size_z": RUN_HEIGHT,\n                "collision": "convex", "material": RUN_MATERIAL})\n            entry["runs"].append(name)\n        _declare_material(spec)\n        entry["queued"] = True\n        entry["lanes"] = got["lanes"]\n        entry["why"] = "%d lanes, %.1f m along %s\'s wall with %s" % (\n            got["lanes"], got["span"][1] - got["span"][0], office.get("id"), got["room"].get("id"))\n        q += 1\n    return report\n', 'migrate_ticket_queue.py': '#!/usr/bin/env python3\n"""\nmigrate_ticket_queue.py  --  give every box office its ticket window and queue\n==============================================================================\nOne-shot, idempotent migration over specs/*.json for the factory\'s roadmap 267\n(the walker, 2026-10-20: "queue lanes to the box office", in retractable-belt\nstanchions). `ticket_queue.queue_box_offices` does the work and `enrich` now\nruns it for every preset, before cover and furniture; this gives the specs\nalready in the library the same answer. A library spec is already furnished, so\nthe queue is fitted round what stands there: nothing inside it, a corridor\nround every line. `lf_*` specs are Level Factory\'s per-run transients and are\nskipped.\n\n    python migrate_ticket_queue.py            # write specs/\n    python migrate_ticket_queue.py --check    # report only\n    python migrate_ticket_queue.py --dir D    # another spec directory\n"""\nimport glob\nimport io\nimport json\nimport os\nimport sys\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, HERE)\n\nimport ticket_queue  # noqa: E402\n\n\ndef main():\n    check = "--check" in sys.argv\n    root = os.path.join(HERE, "specs")\n    if "--dir" in sys.argv:\n        root = sys.argv[sys.argv.index("--dir") + 1]\n    queued = left = 0\n    for p in sorted(glob.glob(os.path.join(root, "*.json"))):\n        name = os.path.basename(p)\n        if name.startswith("lf_"):\n            continue\n        try:\n            d = json.load(open(p, encoding="utf-8"))\n        except ValueError:\n            continue\n        before = json.dumps(d, sort_keys=True)\n        report = ticket_queue.queue_box_offices(d)\n        for r in report:\n            print(f"  {name} {r[\'room\']}: "\n                  f"{\'queued\' if r[\'queued\'] else \'left\'} -- {r[\'why\']}")\n            queued += r["queued"]\n            left += not r["queued"]\n        if not check and json.dumps(d, sort_keys=True) != before:\n            io.open(p, "w", encoding="utf-8", newline="\\n").write(\n                json.dumps(d, indent=1) + "\\n")\n    print(f"[ticket_queue] {queued} box office(s) "\n          f"{\'to queue\' if check else \'queued\'}, {left} left")\n    return 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'test_ticket_queue.py': '"""A box office\'s ticket window and the queue in front of it (0.243.0, the factory\'s roadmap 267; `ticket_queue.py`).\n\nThe walker, 2026-10-20: "queue lanes to the box office", in retractable-belt stanchions -- "metal barriers are for\noutdoor concerts or riot protection from police". Every test here fails on 0.242.0, which has no `ticket_queue`.\n\nTHE CROSS-REPO PINS run when Zoo is found: `$DC_ZOO_ROOT`, else `../zoo`, as `test_vault_room.py`\'s do.\n"""\nimport copy\nimport importlib\nimport json\nimport math\nimport os\nimport sys\nimport types\n\nimport pytest\n\nimport agent_contract\nimport floors\nimport level_design\nimport prop_species\nimport ticket_queue as tq\nimport vault_room\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nZOO = os.environ.get("DC_ZOO_ROOT") or os.path.join(os.path.dirname(HERE), "zoo")\n_PALETTE = [{"id": "concrete", "acoustic": "Concrete"}, {"id": "drywall", "acoustic": "Drywall"},\n            {"id": "glass", "acoustic": "Glass"}, {"id": "metal", "acoustic": "Metal"},\n            {"id": "wood", "acoustic": "Wood"}]\n\n\ndef _theatre(door_pos=0.4, office_id="box_office", public_role="public_entry", extra_doors=()):\n    """A 30 x 20 m theatre: a lobby along the south, the box office and a back room behind a partition at y 2."""\n    return {"name": "t_theatre", "mode": "pvp_heist", "seed": 7, "footprint_x": 30, "footprint_y": 20,\n            "story_height": 4.0, "n_stories": 1, "default_material": "concrete",\n            "materials": copy.deepcopy(_PALETTE),\n            "ext_walls": [{"wall": "S", "story": 0, "openings": [{"kind": "door", "pos": 0.0, "width": 2.4}]}],\n            "partitions": [{"story": 0, "axis": "X", "pos": 2.0, "start": -15.0, "end": 15.0,\n                            "openings": [{"kind": "door", "pos": door_pos, "width": 1.25}]\n                            + [{"kind": "door", "pos": p, "width": 1.25} for p in extra_doors]},\n                           {"story": 0, "axis": "Y", "pos": -5.0, "start": 2.0, "end": 10.0,\n                            "openings": [{"kind": "door", "pos": 0.0, "width": 1.25}]}],\n            "rooms": [{"id": "lobby", "story": 0, "bounds": [-15.0, -10.0, 15.0, 2.0], "role": public_role,\n                       "combat_range": "medium"},\n                      {"id": office_id, "story": 0, "bounds": [-15.0, 2.0, -5.0, 10.0], "role": "objective_room",\n                       "combat_range": "close"},\n                      {"id": "back_room", "story": 0, "bounds": [-5.0, 2.0, 15.0, 10.0], "role": "connector",\n                       "combat_range": "medium"}],\n            "volumes": [], "markers": [], "stairs": [], "ladders": []}\n\n\ndef _arena():\n    with open(os.path.join(HERE, "specs", "arena_a02.json"), encoding="utf-8") as fh:\n        return json.load(fh)\n\n\ndef _runs(spec):\n    return [v for v in spec.get("volumes") or [] if str(v.get("name", "")).startswith("stanchion_run_")]\n\n\ndef _box(v):\n    return (v["x"] - v["size_x"] / 2.0, v["y"] - v["size_y"] / 2.0, v["x"] + v["size_x"] / 2.0,\n            v["y"] + v["size_y"] / 2.0)\n\n\ndef _ticket_window(spec):\n    got = [(p, op) for p in spec.get("partitions") or [] for op in p.get("openings") or []\n           if op.get("tag") == "ticket_window"]\n    assert len(got) == 1, got\n    return got[0]\n\n\n# ---------------------------------------------------------------- the words and the numbers\n\ndef test_a_box_office_is_named_by_its_words():\n    yes = ("box_office", "ticket_booth", "tickets", "boxoffice", "ticketing_hall", "east_box_office")\n    no = ("box_room", "office", "back_office", "post_office", "lobby", "event_floor", "cashier_cage")\n    assert all(tq.is_box_office({"id": r}) for r in yes)\n    assert not any(tq.is_box_office({"id": r}) for r in no)\n\n\ndef test_the_numbers_are_the_contracts():\n    """A lane is a corridor to the bake, so its clear floor is a stair flight\'s: the corridor minimum and one cell. The\n    floor in front of the window is a door\'s approach. Nothing here is a literal a body\'s size could move under."""\n    assert tq.lane_clear() == agent_contract.stair_flight_width()\n    assert math.isclose(tq.pitch(), agent_contract.stair_flight_width() + tq.RUN_DEPTH)\n    assert tq.service_depth() == agent_contract.door_approach()\n    assert tq.line_min() == tq.pitch()\n    assert tq.lane_clear() > agent_contract.min_corridor_width()\n\n\ndef _zoo_genome():\n    path = os.path.join(ZOO, "zoo_keeper", "genome", "species", "stanchion_run.json")\n    if not os.path.isfile(path):\n        pytest.skip("zoo\'s stanchion_run genome not found at %s (set DC_ZOO_ROOT)" % path)\n    with open(path, encoding="utf-8") as fh:\n        return json.load(fh)\n\n\ndef test_the_stanchion_numbers_are_zoos():\n    g = _zoo_genome()\n    dims = g["dimensions"]\n    assert tq.RUN_DEPTH == dims["depth"]["default"] and tq.RUN_HEIGHT == dims["height"]["default"]\n    assert tq.RUN_MIN == dims["width"]["min"]\n    assert g["materials"]["default"] == tq.RUN_MATERIAL and tq.RUN_MATERIAL in g["materials"]["options"]\n    # a line the rule lays is a run Zoo draws\n    assert dims["width"]["min"] <= tq.line_min() and tq.MAX_SPAN - tq.lane_clear() <= dims["width"]["max"]\n\n\ndef test_a_run_is_the_species_and_a_lone_post_is_still_the_single_stanchion():\n    assert prop_species.species_for_name("stanchion_run_0_3") == "stanchion_run"\n    assert prop_species.species_for_name("stanchion_rcce455f7_5") == "queue_stanchion"\n    assert prop_species.owns_collision("stanchion_run")\n    assert level_design._prop_material({"materials": []}, "stanchion_run_0_0") == tq.RUN_MATERIAL\n    # the run\'s name carries no cover word: a belt is not cover\n    assert not level_design._looks_like_cover({"name": "stanchion_run_0_0", "size_x": 4.8, "size_y": 0.356,\n                                               "size_z": tq.RUN_HEIGHT})\n\n\n# ---------------------------------------------------------------- arena_a02, as the library carries it\n\ndef test_arena_a02_sells_through_a_ticket_window_in_the_box_offices_wall():\n    """One window, in the partition between the box office and the event floor, inside the office\'s run, on the\n    builder\'s grid -- so it is cut where its queue was laid -- and a jamb clear of the secure door and the office\'s\n    east wall."""\n    spec = _arena()\n    p, op = _ticket_window(spec)\n    assert (p["axis"], p["pos"]) == ("X", 5.9)\n    assert (op["kind"], op["width"], op["sill"], op["height"], op["vaultable"]) == (\n        "window", tq.WINDOW_W, tq.WINDOW_SILL, tq.WINDOW_H, False)\n    assert "breakable" not in op\n    (e,) = [e for e in vault_room.wall_openings(spec, kinds=("window",)) if e["op"] is op]\n    run = p["end"] - p["start"]\n    assert math.isclose(e["along"], op["pos"] * run, abs_tol=1e-6)\n    office = [r for r in spec["rooms"] if r["id"] == "box_office"][0]\n    w0, w1 = e["along"] - op["width"] / 2.0, e["along"] + op["width"] / 2.0\n    assert office["bounds"][0] + 0.15 + tq.JAMB <= w0 and w1 <= office["bounds"][2] - 0.15 - tq.JAMB\n    for o in vault_room.wall_openings(spec, kinds=("door", "breach")):\n        if o["host"] is p:\n            hw = tq._opening_width(o["op"]) / 2.0\n            assert w1 + tq.JAMB <= o["along"] - hw or o["along"] + hw <= w0 - tq.JAMB, o["op"]\n\n\ndef test_arena_a02s_queue_switches_back_to_the_window():\n    """Four lines, three lanes, parallel to the wall: each line a lane apart, stopping a turn short at alternate ends,\n    the first -- nearest the wall -- short at the window\'s end, so the last lane lets out in front of the window."""\n    spec = _arena()\n    runs = sorted(_runs(spec), key=lambda v: -v["y"])\n    assert [v["name"] for v in sorted(_runs(spec), key=lambda v: v["name"])] == [\n        "stanchion_run_0_%d" % k for k in range(4)]\n    assert all(v["material"] == tq.RUN_MATERIAL and v["size_z"] == tq.RUN_HEIGHT\n               and v["size_y"] == tq.RUN_DEPTH and math.isclose(v["z"], tq.RUN_HEIGHT / 2.0) for v in runs)\n    face = 5.9 - 0.15\n    assert math.isclose(face - _box(runs[0])[3], tq.service_depth(), abs_tol=1e-3)\n    for a, b in zip(runs, runs[1:]):\n        assert math.isclose(_box(a)[1] - _box(b)[3], tq.lane_clear(), abs_tol=1e-3)\n    _p, op = _ticket_window(spec)\n    wx = op["pos"] * 50.0\n    lo = min(_box(v)[0] for v in runs)\n    hi = max(_box(v)[2] for v in runs)\n    ends = [(_box(v)[0], _box(v)[2]) for v in runs]\n    # the window\'s end is the one line 0 stops short of\n    window_low = ends[0][0] > lo + 1e-6\n    for k, (x0, x1) in enumerate(ends):\n        short_at_window = (k % 2 == 0)\n        short_low = x0 > lo + 1e-6\n        assert short_low == (short_at_window == window_low), (k, x0, x1)\n        assert math.isclose((x1 - x0), hi - lo - tq.lane_clear(), abs_tol=1e-3)\n    gap = (lo, lo + tq.lane_clear()) if window_low else (hi - tq.lane_clear(), hi)\n    assert gap[0] - 1e-6 <= wx - tq.WINDOW_W / 2.0 and wx + tq.WINDOW_W / 2.0 <= gap[1] + 1e-6\n\n\ndef test_arena_a02s_queue_stands_clear_of_everything():\n    """Measured from the spec, not asked of `ticket_queue`: nothing else stands inside the queue, wall face to the\n    last line, and every line keeps `min_corridor_width()` from every other standing volume in the event floor, every\n    walkable opening\'s approach and the walls but its own."""\n    spec = _arena()\n    cw = agent_contract.min_corridor_width()\n    runs = _runs(spec)\n    rect = (min(_box(v)[0] for v in runs), min(_box(v)[1] for v in runs),\n            max(_box(v)[2] for v in runs), 5.9 - 0.15)\n    floor_room = [r for r in spec["rooms"] if r["id"] == "event_floor"][0]["bounds"]\n    others = [v for v in spec["volumes"] if v not in runs and v["z"] - v["size_z"] / 2.0 < 2.0]\n    for v in others:\n        b = _box(v)\n        assert not (b[0] < rect[2] and rect[0] < b[2] and b[1] < rect[3] and rect[1] < b[3]), v["name"]\n        if floor_room[0] <= v["x"] <= floor_room[2] and floor_room[1] <= v["y"] <= floor_room[3]:\n            for r in runs:\n                assert level_design._box_gap(_box(r), b) >= cw - 1e-9, (r["name"], v["name"])\n    da = agent_contract.door_approach()\n    for e in vault_room.wall_openings(spec, kinds=("door", "garage", "breach", "vault")):\n        if e["story"] != 0:\n            continue\n        hw, d = tq._opening_width(e["op"]) / 2.0, 0.15 + da\n        ap = ((e["along"] - hw, e["line"] - d, e["along"] + hw, e["line"] + d) if e["axis"] == "X"\n              else (e["line"] - d, e["along"] - hw, e["line"] + d, e["along"] + hw))\n        clipped = (max(ap[0], floor_room[0]), max(ap[1], floor_room[1]), min(ap[2], floor_room[2]),\n                   min(ap[3], floor_room[3]))\n        if clipped[2] - clipped[0] <= 1e-6 or clipped[3] - clipped[1] <= 1e-6:\n            continue\n        for r in runs:\n            assert level_design._box_gap(_box(r), clipped) >= cw - 1e-9, (r["name"], e["op"])\n    # the event floor\'s west wall, the nearest wall but the queue\'s own\n    for r in runs:\n        assert _box(r)[0] - (-25.0 + 0.15) >= cw\n\n\ndef test_arena_a02_keeps_no_steel_barricade_and_declares_the_stanchions_kind_last():\n    """0.242.0\'s four crowd barricades stood across arena_a02\'s event floor; the walker: "metal barriers are for\n    outdoor concerts or riot protection from police". They and `metal_bare`, which they alone wore, are gone, and\n    `metal_painted` is declared after the finish palette, so no finish slot\'s style moved."""\n    spec = _arena()\n    assert not [v for v in spec["volumes"] if "barrier" in v["name"].lower()]\n    ids = [m["id"] for m in spec["materials"]]\n    assert ids == ["concrete", "drywall", "glass", "metal", "wood", "carpet", "tile", "ceiling_tile", "plaster",\n                   "metal_painted"]\n\n\ndef test_the_library_is_a_fixed_point_of_the_rule():\n    """Re-run over every library spec, the rule changes nothing: arena_a02 already has its queue, and no other spec\n    has a box office."""\n    import glob\n    offices = []\n    for path in sorted(glob.glob(os.path.join(HERE, "specs", "*.json"))):\n        if os.path.basename(path).startswith("lf_"):\n            continue\n        with open(path, encoding="utf-8") as fh:\n            spec = json.load(fh)\n        before = json.dumps(spec, sort_keys=True)\n        tq.queue_box_offices(spec)\n        assert json.dumps(spec, sort_keys=True) == before, path\n        offices += [(os.path.basename(path), r["id"]) for r in spec.get("rooms") or [] if tq.is_box_office(r)]\n    assert offices == [("arena_a02.json", "box_office")]\n\n\n# ---------------------------------------------------------------- the rule, on a building made for it\n\ndef test_a_theatre_gets_three_lanes_and_its_window():\n    spec = _theatre()\n    (r,) = tq.queue_box_offices(spec)\n    assert r["queued"] and r["lanes"] == 3 and len(r["runs"]) == 4, r\n    _p, op = _ticket_window(spec)\n    assert op["kind"] == "window"\n    # idempotent: a second pass adds nothing and reports nothing\n    before = json.dumps(spec, sort_keys=True)\n    assert tq.queue_box_offices(spec) == []\n    assert json.dumps(spec, sort_keys=True) == before\n\n\ndef test_declaring_the_kind_moves_no_style():\n    """A slot\'s style is its material\'s place in `floors.palette_ids`. The rule declares the finish palette before\n    `metal_painted` when a spec has not, so every material the spec could already name keeps its place."""\n    from spec_loader import spec_from_dict\n    spec = _theatre()\n    before = floors.palette_ids(spec_from_dict(copy.deepcopy(spec)))\n    tq.queue_box_offices(spec)\n    after = floors.palette_ids(spec_from_dict(copy.deepcopy(spec)))\n    assert after[:len(before)] == before and after[len(before):] == [tq.RUN_MATERIAL], (before, after)\n\n\ndef test_a_box_office_with_no_public_neighbour_gets_none():\n    spec = _theatre(public_role="connector")\n    spec["rooms"][0]["id"] = "yard"\n    (r,) = tq.queue_box_offices(spec)\n    assert not r["queued"] and r["why"] == "no interior wall shared with a public room", r\n    assert not _runs(spec) and not any(op.get("tag") for p in spec["partitions"] for op in p["openings"])\n\n\ndef test_a_wall_full_of_doors_leaves_the_queue_unlaid_and_says_why():\n    """Doors every three metres along the office\'s wall: no window clears them by a jamb with a queue clear of their\n    approaches, and the rule lays nothing rather than a queue in a doorway."""\n    spec = _theatre(door_pos=-0.4, extra_doors=(-0.3, -0.2, -0.1, 0.0))\n    (r,) = tq.queue_box_offices(spec)\n    assert not r["queued"] and r["why"], r\n    assert not _runs(spec)\n\n\ndef test_enrich_lays_the_queue_before_cover_and_furniture():\n    """`enrich` lays the queue before it seeds cover and furnishes, so nothing it places stands in a lane."""\n    spec = _theatre()\n    rep = level_design.enrich(spec)\n    assert rep["queues_laid"] == 1, rep\n    runs = _runs(spec)\n    rect = (min(_box(v)[0] for v in runs), min(_box(v)[1] for v in runs), max(_box(v)[2] for v in runs), 2.0 - 0.15)\n    placed = [v for v in spec["volumes"] if v not in runs]\n    assert placed, "enrich placed nothing: the check below would pass vacuously"\n    for v in placed:\n        if v.get("collision") == "none" and v["z"] - v["size_z"] / 2.0 >= 1.8:\n            continue\n        b = _box(v)\n        assert not (b[0] < rect[2] and rect[0] < b[2] and b[1] < rect[3] and rect[1] < b[3]), v["name"]\n\n\n# ---------------------------------------------------------------- the builder\n\n@pytest.fixture\ndef dc(monkeypatch):\n    """deli_counter against stub bpy/bmesh, as test_prop_species does."""\n    for name in ("bpy", "bmesh"):\n        try:\n            importlib.import_module(name)\n        except ImportError:\n            monkeypatch.setitem(sys.modules, name, types.ModuleType(name))\n    monkeypatch.delitem(sys.modules, "deli_counter", raising=False)\n    mod = importlib.import_module("deli_counter")\n    yield mod\n    sys.modules.pop("deli_counter", None)\n\n\ndef test_the_builder_writes_each_line_as_the_species_with_no_box(dc):\n    """Each line is a `stanchion_run` slot, its long side the module\'s width, its collision the module\'s own -- no\n    greybox box, which would be a 0.97 m wall where a belt is."""\n    import skin_style\n    from spec_loader import spec_from_dict\n    spec = _theatre()\n    tq.queue_box_offices(spec)\n    s = spec_from_dict(spec)\n    b = dc._Builder(s)\n    b.slots = []\n    b._mat_style = skin_style.material_styles([m.id for m in s.materials])\n    cols = []\n    b._box = lambda *a, **k: None\n    b._col_box = lambda name, *a, **k: cols.append(name)\n    b._record_surface = lambda *a, **k: None\n    b._volumes()\n    slots = {x["slot_id"]: x for x in b.slots}\n    assert sorted(slots) == ["stanchion_run_0_%d" % k for k in range(4)], sorted(slots)\n    assert not [c for c in cols if c.startswith("stanchion_run_")], cols\n    for x in slots.values():\n        assert x["species"] == "stanchion_run" and x["fit"]["collision"] == "none", x\n        assert x["fit"]["dims"] == [4.8, tq.RUN_DEPTH, tq.RUN_HEIGHT], x["fit"]\n'}
CHANGELOG = '## [0.243.0] - a box office sells through a ticket window, and its queue switches back in front of it\n\n**The factory\'s roadmap 267, the walker, 2026-10-20.** Asked what arena_a02\'s four steel barricades on its event floor\nwere for, the walker chose "queue lanes to the box office"; then "stanchion or stanchions are likley more common for\nbanks and indoor common areas", "metal barriers are for outdoor concerts or riot protection from police", "retractable\nbelt stanchion", and a photo of a queue lined with them. Zoo 1.119.0 draws one straight run of those stanchions,\n`stanchion_run`. This lays a box office\'s queue of them, as generator logic, and takes the barricades indoors away.\n\n### Added\n- **`ticket_queue.py`**, pure. A room whose id names a box office or a ticket office (`is_box_office`: `box` with\n  `office`, `ticket`, `tickets`, `ticketing`, `boxoffice`) that shares an interior wall with a public room (the role\n  `public_entry`, or a lobby or a hall by its words) gets:\n  - **a ticket window** in that wall: a `window` opening tagged `ticket_window`, 1.2 m wide over a 1.0 m sill, 1.1 m\n    tall, sealed -- not `breakable`, since a pane that shot out would be a firing line into the room behind it -- on\n    the builder\'s grid, so it is cut where its queue was laid, and a jamb clear of the wall\'s openings and of any wall\n    ending on it;\n  - **a queue** in front of it, on the public side: three lanes or two between lines of stanchion runs parallel to the\n    wall, one `stanchion_run_<q>_<k>` volume a line, each line stopping a turn short at alternate ends, so the queue\n    switches back -- in at the end away from the window, out of the last lane at the window\'s end onto the floor in\n    front of the window.\n  Every clearance is the body contract\'s: a lane\'s clear floor and a turn are `stair_flight_width()` (a corridor and\n  one bake cell, a lane being a corridor to the bake); the floor in front of the window is `door_approach()`; nothing\n  stands inside the queue, and every line keeps `min_corridor_width()` from every wall but its own, every standing\n  volume, every walkable opening\'s approach, every stair, hole and vault swing. `plan` tries every window place the\n  grid allows, at either end, three lanes then two, as long as 6 m and shorter in 0.1 m steps to a line as long as the\n  lanes are wide, and keeps the most lanes, then the longest, then the window nearest the middle of the office\'s wall.\n  A box office whose only outside wall is the street\'s is the street\'s queue, and Lot\'s; this reports it and lays\n  nothing. `RUN_DEPTH`, `RUN_HEIGHT` and the kind are Zoo\'s genome\'s, retyped and pinned by a test when the zoo repo is\n  beside this one, as the vault door\'s are.\n- **`level_design.enrich`** lays the queue after the teller line and the vault and before cover and furniture\n  (`queues_laid`), so a generated building\'s cover and furniture clear its lines and its window.\n- **`migrate_ticket_queue.py`**: the library\'s box offices get the same answer, fitted round what is already there.\n- **`PROP_SPECIES`**: `stanchion_run` routes to the species, above `stanchion`, whose single post a lone\n  `stanchion_*` still is; `SPECIES_OWNS_COLLISION` holds it -- the module\'s collider is the posts and the belt line, and\n  a box the slot\'s size would be a 0.97 m wall a crouching body hides behind, cover a belt is not.\n  `level_design._PROP_MATERIALS`: a run is `metal_painted`, its species\' own kind.\n\n### Changed\n- **`specs/arena_a02.json`**, the library\'s one box office:\n  - the four steel barricades 0.242.0 routed to Zoo\'s `crowd_barrier` (`barrier_0` to `_3`, 3.0 x 0.8 x 1.2 m across\n    the event floor) are gone -- the walker: the steel barricade is for outdoor concerts and police lines -- and\n    `metal_bare`, which they alone wore, with them;\n  - `migrate_ticket_queue` laid the box office\'s queue: the window in the partition at y 5.9 at x -15.5, between the\n    box office\'s secure door and its east wall, and three lanes, 6.0 m along the event floor\'s north wall eastward from\n    the window, four lines of 4.8 m; `metal_painted` declared last, after the finish palette, style 10;\n  - **refurnished** (`migrate_furnish_recipes.migrate`, arena_a02 alone), because the library is a fixed point of\n    furnish and a piece removed or added moves what furnish places round it: ten of the event floor\'s furnished pieces\n    -- cartons and litter bins -- stand elsewhere, none inside the queue. The rest of the library is untouched.\n- `combat_audit --rules auto` reads arena_a02 the same before and after: 0 HIGH, 1 MED, 4 INFO, the box office\'s\n  sightline 12.7 m. The barricades were 1.2 m, under the contract\'s 1.3 m cover-break height, so no sightline they cut\n  opens; the event floor\'s cover-like pieces go 21 -> 17.\n\n### Tests\n- `test_ticket_queue.py` (new): the words that name a box office; every number the contract\'s; the stanchion numbers\n  Zoo\'s genome\'s; a run is the species and owns its collision, and a lone post is still the single stanchion;\n  arena_a02 sells through one window in the box office\'s wall, on the grid and clear of its door; its queue switches\n  back to the window, a lane\'s clear floor apart; nothing stands inside it and every line keeps a corridor from every\n  volume, opening approach and wall, measured from the spec; no steel barricade and `metal_painted` last; the library\n  is a fixed point of the rule; a theatre built for it gets three lanes and its window, once; declaring the kind moves\n  no style; no public neighbour and a wall full of doors each leave it unlaid with a reason; `enrich` lays it before\n  cover and furniture and nothing stands in it; the builder writes each line as the species with no greybox box.\n  It cannot import on 0.242.0.\n- `test_prop_species.py`: `test_barrier_routes_to_the_crowd_barrier_and_none_stands_in_the_arena` replaces 0.242.0\'s\n  barrier test -- the word still routes to the barricade; arena_a02 carries none and no `metal_bare`. It fails on\n  0.242.0.\n- `test_cover_breaks_sightlines.py`: `enrich`\'s report carries `queues_laid`.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.242.0', 'Deli Counter 0.243.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
